  /* ── Multiplayer: shared Lix documents ──
   * When a Pro user shares a folio, its local Lix blob is promoted to a
   * server-hosted instance. Collaborators open it with Lix sync enabled and
   * `initSyncProcess` pushes/pulls change-sets through the /lsp/* relay. */

  sharedLixBlobs: defineTable({
    lixId: v.string(),
    ownerId: v.string(),
    folioId: v.string(),
    folioName: v.string(),
    storageId: v.id("_storage"),
    createdAt: v.number(),
    updatedAt: v.number(),
  })
    .index("by_lixId", ["lixId"])
    .index("by_ownerId", ["ownerId"]),

  // ── Push-serialization locks — one row per in-flight push. ──
  // Prevents two concurrent /lsp/push-v1 requests from both reading the
  // same base blob and the later write clobbering the earlier one.
  // Stale locks (older than LIX_LOCK_TTL_MS) are reclaimed automatically.
  lixLocks: defineTable({
    lixId: v.string(),
    lockedAt: v.number(),
  }).index("by_lixId", ["lixId"]),

  collaborators: defineTable({
    lixId: v.string(),
    userId: v.string(),
    role: v.union(
      v.literal("owner"),
      v.literal("editor"),
      v.literal("commenter"),
    ),
    status: v.union(
      v.literal("pending"),
      v.literal("accepted"),
      v.literal("rejected"),
    ),
    invitedBy: v.optional(v.string()),
    invitedAt: v.number(),
    acceptedAt: v.optional(v.number()),
  })
    .index("by_lixId", ["lixId"])
    .index("by_userId", ["userId"])
    .index("by_lixId_userId", ["lixId", "userId"]),

  presence: defineTable({
    lixId: v.string(),
    userId: v.string(),
    displayName: v.string(),
    email: v.optional(v.string()),
    color: v.string(),
    cursorPos: v.optional(v.number()),
    selectionAnchor: v.optional(v.number()),
    selectionHead: v.optional(v.number()),
    lastSeenAt: v.number(),
  })
    .index("by_lixId", ["lixId"])
    .index("by_lixId_userId", ["lixId", "userId"]),

  // ── Mobile app waitlist — public, unauthenticated signups. ──
  // One row per (email, platform); dedupe is enforced in convex/waitlist.ts
  // via the index below rather than a unique constraint (Convex has none).
  waitlist: defineTable({
    email: v.string(),
    platform: v.union(v.literal("ios"), v.literal("android")),
    createdAt: v.number(),
  }).index("by_email_platform", ["email", "platform"]),

  // ── Rate-limit buckets — one row per (action, identifier). ──
  // Identifier is usually the user's Convex tokenIdentifier; for
  // unauthed paths (OTP request) it's the email or IP. `count` is
  // reset when `windowStart` is older than the action's window.
  // See convex/lib/rateLimit.ts.
  rateBuckets: defineTable({
    action: v.string(),
    identifier: v.string(),
    count: v.number(),
    windowStart: v.number(),
  }).index("by_action_identifier", ["action", "identifier"]),
});

import type { AiFeature } from "../src/types";
import {
  createAiTraceId,
  deterministicEvalProperties,
  serializeAiContent,
  type AiContentMode,
  type AiUsage,
} from "../src/utils/ai-deterministic-evals";
import type { AgentRequest } from "./agentPrompts";

export interface ServerAiObservabilityContext {
  distinctId?: string;
  anonymousId?: string;
  sessionId?: string;
  folioId?: string;
  editorialActionId?: string;
  traceId?: string;
}

export interface CaptureServerAiGenerationArgs {
  feature: AiFeature;
  provider: string;
  model: string;
  req?: AgentRequest;
  generationInput?: string;
  personaId?: string;
  output?: string;
  latencyMs: number;
  temperature?: number;
  maxTokens?: number;
  spanName?: string;
  error?: unknown;
  usage?: AiUsage;
  observability?: ServerAiObservabilityContext;
  evalSignals?: Record<string, unknown>;
}

function projectKey(): string | undefined {
  return process.env.POSTHOG_PROJECT_API_KEY ?? process.env.PUBLIC_POSTHOG_KEY;
}

function host(): string {
  return process.env.POSTHOG_HOST ?? "https://us.i.posthog.com";
}

function captureEnabled(): boolean {
  return process.env.POSTHOG_CAPTURE !== "false";
}

function contentMode(): AiContentMode {
  return process.env.POSTHOG_AI_CONTENT_MODE === "full" ? "full" : "redacted";
}

function errorValue(error: unknown): unknown {
  if (!error) return undefined;
  if (error instanceof Error) {
    return { message: error.message.slice(0, 400), name: error.name };
  }
  return String(error).slice(0, 400);
}

export async function captureServerAiGeneration({
  feature,
  provider,
  model,
  req,
  generationInput,
  output,
  latencyMs,
  temperature,
  maxTokens,
  spanName,
  error,
  usage,
  observability,
  personaId,
  evalSignals,
}: CaptureServerAiGenerationArgs): Promise<string> {
  const resolvedTraceId =
    observability?.traceId ?? createAiTraceId(String(feature));
  const apiKey = projectKey();
  if (!apiKey || !captureEnabled()) return resolvedTraceId;

  try {
    const mode = contentMode();
    const input =
      inputForGeneration(req, generationInput) ??
      JSON.stringify({
        persona: req?.persona.id,
        instruction: req?.instruction ?? "feedback",
        hasBrief: !!req?.brief,
        draftText: req?.draftText,
        anchor: req?.anchor,
        userMessage: req?.userMessage,
      });
    await fetch(`${host().replace(/\/$/, "")}/i/v0/e/`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        api_key: apiKey,
        event: "$ai_generation",
        properties: {
          distinct_id: observability?.distinctId ?? `convex:${feature}`,
          $ai_trace_id: resolvedTraceId,
          $ai_session_id: observability?.sessionId,
          $ai_span_id: createAiTraceId(`${feature}:server-generation`),
          $ai_span_name: spanName ?? feature,
          $ai_model: model,
          $ai_provider: provider,
          $ai_input: [
            {
              role: "user",
              content: serializeAiContent(input, mode),
            },
          ],
          $ai_output_choices: output
            ? [{ role: "assistant", content: serializeAiContent(output, mode) }]
            : [],
          $ai_input_tokens: usage?.inputTokens,
          $ai_output_tokens: usage?.outputTokens,
          $ai_latency: latencyMs / 1000,
          $ai_temperature: temperature,
          $ai_max_tokens: maxTokens,
          $ai_is_error: !!error,
          $ai_error: errorValue(error),
          twyne_feature: feature,
          twyne_persona_id: personaId ?? req?.persona.id,
          twyne_instruction: req?.instruction ?? "feedback",
          twyne_server_runtime: "convex",
          twyne_anonymous_id: observability?.anonymousId,
          twyne_session_id: observability?.sessionId,
          twyne_folio_id: observability?.folioId,
          twyne_editorial_action_id: observability?.editorialActionId,
          twyne_content_mode: mode,
          twyne_input_chars: input.length,
          twyne_output_chars: output?.length ?? 0,
          ...deterministicEvalProperties(output, evalSignals),
          ...evalSignals,
        },
      }),
    });
  } catch (err) {
    console.warn("[twyne:posthog] failed to capture AI generation:", err);
  }
  return resolvedTraceId;
}

function inputForGeneration(
  req: AgentRequest | undefined,
  input: string | undefined,
): string | undefined {
  if (input !== undefined) return input;
  if (!req) return undefined;
  return JSON.stringify({
    persona: req.persona.id,
    instruction: req.instruction ?? "feedback",
    hasBrief: !!req.brief,
    draftText: req.draftText,
    anchor: req.anchor,
    userMessage: req.userMessage,
  });
}

